 for k in sorted(given,key=len,reverse=True):
  import re
  numeric=re.sub(r'\b'+k+r'\b','('+format(given[k][0],'.15g')+')',numeric)
 BANK.append(dict(key=key,ch=ch,title=title,prompt=prompt,given=[{'symbol':k,'value':v[0],'unit':v[1],'meaning':v[2]} for k,v in given.items()],expression=expr,numeric=numeric,latex=sp.latex(ex),unit=unit,value=value,assumptions=assumptions,model=model,interpretation=interpretation,independent=independent,limitations=limitations))
